namespace Og.Core.Runtime;

public delegate CommandResult CommandHandler(GameEngine engine, Session session, string argument);

/// <summary>
/// The verbs the engine itself knows. Registered rather than hardcoded, so new
/// ones can be added without editing this file.
/// </summary>
public sealed class CommandRegistry
{
    private readonly Dictionary<string, CommandHandler> _exact = new(StringComparer.OrdinalIgnoreCase);
    private readonly List<(string Prefix, CommandHandler Handler)> _prefixes = [];

    /// <summary>
    /// Verbs never reached by guesswork. The four directions are one letter away
    /// from words that mean something else entirely — "rest" is not "west" — and
    /// moving somebody who did not ask to move is worse than not understanding them.
    /// Running is a move as well, and "flea" is not "flee".
    ///
    /// Retracing is a move too, and it is the one most easily arrived at by
    /// accident: "back" is a single slip from "pack", "lack", "hack" and "bank",
    /// and a person who typed one of those and found themselves in the previous
    /// room would have no idea what they had done.
    ///
    /// The door words are here for the same reason, only more so: ending a life
    /// nobody asked to end is the worst thing a guess could do.
    /// </summary>
    private static readonly HashSet<string> NeverCorrectedTo =
        new(StringComparer.OrdinalIgnoreCase)
        {
            "north", "south", "east", "west", "flee", "retreat", "withdraw",
            "back", "return", "backtrack", "retrace",
            "exit", "escape", "leave"
        };

    public IReadOnlyCollection<string> Verbs => _exact.Keys;

    public void RegisterExact(CommandHandler handler, params string[] forms)
    {
        foreach (var form in forms)
        {
            _exact[form] = handler;
        }
    }

    public void RegisterPrefix(CommandHandler handler, params string[] prefixes)
    {
        foreach (var prefix in prefixes)
        {
            _prefixes.Add((prefix, handler));
        }
    }

    /// <summary>
    /// Matches on the normalised command but hands the handler the argument as the
    /// player actually typed it, so speech keeps its punctuation and capitals.
    /// </summary>
    public CommandResult Execute(GameEngine engine, Session session, string command, string raw)
    {
        if (_exact.TryGetValue(command, out var exactHandler))
        {
            return exactHandler(engine, session, "");
        }

        foreach (var (prefix, handler) in _prefixes.OrderByDescending(entry => entry.Prefix.Length))
        {
            if (!command.StartsWith(prefix + " ", StringComparison.OrdinalIgnoreCase))
            {
                continue;
            }

            var argument = raw.Length > prefix.Length && raw.StartsWith(prefix, StringComparison.OrdinalIgnoreCase)
                ? raw[prefix.Length..].Trim()
                : command[(prefix.Length + 1)..].Trim();

            return handler(engine, session, argument);
        }

        // A last chance for a slipped key. One word, one edit, and only when a
        // single verb is that close: "killl" is not a mystery, and answering it
        // with "Nothing happens" teaches people that the world is deaf.
        if (command.Length >= 4 && !command.Contains(' '))
        {
            var candidates = _exact.Keys.Where(verb =>
                verb.Length >= 4 && !verb.Contains(' ') && !NeverCorrectedTo.Contains(verb));

            if (TriggerMatcher.Nearest(command, candidates, 1) is { } corrected)
            {
                return _exact[corrected](engine, session, "");
            }
        }

        return CommandResult.NotHandled;
    }
}

using Og.Core.Runtime;

namespace Og.Core.Tests;

/// <summary>
/// Things people actually typed at this world and were refused for: "take all"
/// over a dead man's belongings, "equip sword" while holding a shortsword,
/// "run away!" in front of a troll, "Take the chisel" at the one thing in this
/// valley holding a chisel, and "Back" at a door.
/// </summary>
public class ReachingForThingsTests
{
    [Fact]
    public void ASwordIsWhatAShortswordIs()
    {
        var world = WorldFixture.Starter();

        Assert.True(world.CreateItem("shortsword")!.Matches("sword"));
        Assert.True(world.CreateItem("health potion")!.Matches("potion"));
        Assert.True(world.CreateItem("leather armor")!.Matches("armour"));
        Assert.True(world.CreateItem("leather armor")!.Matches("leather"));
    }

    [Fact]
    public void OneThingIsNotAnother()
    {
        var world = WorldFixture.Starter();

        Assert.False(world.CreateItem("bone")!.Matches("key"));
        Assert.False(world.CreateItem("dagger")!.Matches("sword"));
        Assert.False(world.CreateItem("shiny spoon")!.Matches("bone"));
    }

    [Fact]
    public void TakeAllPicksUpEverythingOnTheFloor()
    {
        var (engine, _) = WorldFixture.NewEngine();
        var (alice, _) = WorldFixture.Join(engine, "Alice");
        var (bob, bobOut) = WorldFixture.Join(engine, "Bob");

        engine.HandleInput(alice, "east");
        engine.HandleInput(alice, "search the camp");
        WorldFixture.Kill(engine, alice);

        engine.HandleInput(bob, "east");
        engine.HandleInput(bob, "take all");

        Assert.Contains(bob.Character.Inventory, item => item.Name == "dagger");
        Assert.Contains(bob.Character.Inventory, item => item.Name == "shiny spoon");
        Assert.Contains(bob.Character.Inventory, item => item.Name == "health potion");
        Assert.Empty(engine.CurrentLocation(bob)!.Items);
        Assert.Contains("You take the", bobOut.Text);
    }

    [Fact]
    public void TakeAllOnAnEmptyFloorSaysSo()
    {
        var (engine, _) = WorldFixture.NewEngine();
        var (alice, aliceOut) = WorldFixture.Join(engine, "Alice");

        engine.HandleInput(alice, "take all");

        Assert.Contains("nothing here to take", aliceOut.Text);
        Assert.Empty(alice.Character.Inventory);
    }

    // ---- the article ----------------------------------------------------------
    //
    // "take the chisel" is how a person says it. Until the object of a verb had
    // its fillers stripped, the world looked for a thing called "the chisel".

    [Fact]
    public void TheArticleDoesNotHideTheThing()
    {
        var (engine, _) = WorldFixture.NewEngine();
        var (alice, _) = WorldFixture.Join(engine, "Alice");
        var (bob, bobOut) = WorldFixture.Join(engine, "Bob");

        engine.HandleInput(alice, "east");
        engine.HandleInput(alice, "search the camp");
        WorldFixture.Kill(engine, alice);

        engine.HandleInput(bob, "east");
        engine.HandleInput(bob, "take the spoon");

        Assert.Contains(bob.Character.Inventory, item => item.Name == "shiny spoon");
        Assert.DoesNotContain("no the spoon", bobOut.Text);
    }

    [Fact]
    public void TheArticleDoesNotHideWhatYouAreHolding()
    {
        var (engine, _) = WorldFixture.NewEngine();
        var (alice, aliceOut) = WorldFixture.Join(engine, "Alice");

        engine.HandleInput(alice, "equip the dagger");

        Assert.Equal("dagger", alice.Character.Weapon?.Name);
        Assert.DoesNotContain("aren't carrying a the dagger", aliceOut.Text);
    }

    [Fact]
    public void LookingAtTheCreatureWithAnArticle()
    {
        var (engine, _) = WorldFixture.NewEngine();
        var (alice, aliceOut) = WorldFixture.Join(engine, "Alice");

        engine.HandleInput(alice, "north");
        engine.HandleInput(alice, "look at the goblin");

        Assert.DoesNotContain("aren't carrying a the goblin", aliceOut.Text);
        Assert.Contains("HP:", aliceOut.Text);
    }

    // ---- what something else is holding ---------------------------------------
    //
    // A room whose own description names a shortsword answering "there is no
    // sword here to take" was the oldest lie in this world. It is here. It is in
    // something's hand, and that is what should be said.

    [Fact]
    public void WhatTheGoblinIsHoldingIsNotDeniedOutright()
    {
        var (engine, _) = WorldFixture.NewEngine();
        var (alice, aliceOut) = WorldFixture.Join(engine, "Alice");

        engine.HandleInput(alice, "north");
        engine.HandleInput(alice, "take sword");

        Assert.DoesNotContain("There is no sword here to take", aliceOut.Text);
        Assert.Contains("goblin", aliceOut.Text);
        Assert.DoesNotContain(alice.Character.Inventory, item => item.Name == "shortsword");
    }

    [Fact]
    public void AskingForTheChiselIsAnsweredByTheEngineNotSwallowedByAGlob()
    {
        var (engine, _) = WorldFixture.NewEngine();
        var (alice, aliceOut) = WorldFixture.Join(engine, "Alice");

        // Spawn, north to the cave mouth, north to the deep passage, east to the
        // sunken stair. Nothing has to be fought to get there.
        engine.HandleInput(alice, "north");
        engine.HandleInput(alice, "north");
        engine.HandleInput(alice, "east");

        Assert.Equal(8, alice.CurrentLocationId);

        engine.HandleInput(alice, "take the chisel");

        // Edward asked this three times and was told, three times, only that
        // there was iron in the water — never that the way to it was through the
        // man holding it.
        Assert.Contains("drowned man", aliceOut.Text);
        Assert.Contains("come off the dead", aliceOut.Text);
        Assert.DoesNotContain("he is not using it", aliceOut.Text);
    }

    [Fact]
    public void KillingTheHolderPutsItOnTheFloorWhereTakingWorks()
    {
        var (engine, _) = WorldFixture.NewEngine();
        var (alice, aliceOut) = WorldFixture.Join(engine, "Alice");

        engine.HandleInput(alice, "north");
        engine.HandleInput(alice, "north");
        engine.HandleInput(alice, "east");

        var stair = engine.CurrentLocation(alice)!;
        stair.Monster!.HitPoints = 0;
        stair.Items.AddRange(stair.Monster.Inventory);
        stair.Monster = null;

        engine.HandleInput(alice, "take the chisel");

        Assert.Contains(alice.Character.Inventory, item => item.Name == "rusted chisel");
        Assert.Contains("You take the rusted chisel", aliceOut.Text);
    }

    [Fact]
    public void TakeAllSaysWhatTheCreatureIsHolding()
    {
        var (engine, _) = WorldFixture.NewEngine();
        var (alice, aliceOut) = WorldFixture.Join(engine, "Alice");

        engine.HandleInput(alice, "north");
        engine.HandleInput(alice, "take all");

        Assert.DoesNotContain("There is nothing here to take.", aliceOut.Text);
        Assert.Contains("goblin is holding", aliceOut.Text);
    }

    [Fact]
    public void LookingAtWhatACreatureHolds()
    {
        var (engine, _) = WorldFixture.NewEngine();
        var (alice, aliceOut) = WorldFixture.Join(engine, "Alice");

        engine.HandleInput(alice, "north");
        engine.HandleInput(alice, "examine the shortsword");

        Assert.Contains("The goblin has it.", aliceOut.Text);
    }

    // ---- back -----------------------------------------------------------------

    [Fact]
    public void BackRetracesTheWayYouCame()
    {
        var (engine, _) = WorldFixture.NewEngine();
        var (alice, _) = WorldFixture.Join(engine, "Alice");
        var home = alice.CurrentLocationId;

        engine.HandleInput(alice, "north");
        Assert.NotEqual(home, alice.CurrentLocationId);

        engine.HandleInput(alice, "back");

        Assert.Equal(home, alice.CurrentLocationId);
    }

    [Fact]
    public void BackWhereYouStartedAdmitsItRatherThanSayingNothing()
    {
        var (engine, _) = WorldFixture.NewEngine();
        var (alice, aliceOut) = WorldFixture.Join(engine, "Alice");

        engine.HandleInput(alice, "back");

        Assert.Contains("not come from anywhere yet", aliceOut.Text);
        Assert.Equal(1, alice.CurrentLocationId);
    }

    [Fact]
    public void BackIsNotFleeing()
    {
        var (engine, _) = WorldFixture.NewEngine();
        var (alice, aliceOut) = WorldFixture.Join(engine, "Alice");

        engine.HandleInput(alice, "north");
        engine.HandleInput(alice, "back");

        // Fleeing says something about the creature you turned your back on.
        // Walking back the way you came is not a retreat and should not claim to be.
        Assert.DoesNotContain("does not follow", aliceOut.Text);
    }

    /// <summary>
    /// Retracing is a move, and the guesser must not be able to arrive at it.
    /// "pack" is one slip from "back", and a person who typed it and found
    /// themselves in the previous room would have no idea what they had done.
    /// </summary>
    [Fact]
    public void BackIsNotReachedByGuesswork()
    {
        var (engine, _) = WorldFixture.NewEngine();
        var (alice, _) = WorldFixture.Join(engine, "Alice");

        engine.HandleInput(alice, "north");
        var cave = alice.CurrentLocationId;

        engine.HandleInput(alice, "pack");
        engine.HandleInput(alice, "lack");
        engine.HandleInput(alice, "bank");

        Assert.Equal(cave, alice.CurrentLocationId);
    }

    // ---- unchanged --------------------------------------------------------------

    [Fact]
    public void RunningAwayGoesBackTheWayYouCame()
    {
        var (engine, _) = WorldFixture.NewEngine();
        var (alice, _) = WorldFixture.Join(engine, "Alice");
        var home = alice.CurrentLocationId;

        engine.HandleInput(alice, "north");
        var cave = alice.CurrentLocationId;
        Assert.NotEqual(home, cave);

        engine.HandleInput(alice, "run away");

        Assert.Equal(home, alice.CurrentLocationId);
    }

    [Fact]
    public void RunningIsNotCorrectedToFromAnythingElse()
    {
        var (engine, _) = WorldFixture.NewEngine();
        var (alice, _) = WorldFixture.Join(engine, "Alice");
        var home = alice.CurrentLocationId;

        // One edit from "flee", and not a request to be moved.
        engine.HandleInput(alice, "flea");

        Assert.Equal(home, alice.CurrentLocationId);
    }

    [Fact]
    public void TheGroundRemembersWhoDiedOnIt()
    {
        var (engine, _) = WorldFixture.NewEngine();
        var (alice, _) = WorldFixture.Join(engine, "Alice");

        engine.HandleInput(alice, "east");
        var camp = engine.CurrentLocation(alice)!;
        WorldFixture.Kill(engine, alice, "a goblin");

        var (bob, bobOut) = WorldFixture.Join(engine, "Bob");
        engine.HandleInput(bob, "east");

        Assert.Contains("Alice, killed by a goblin.", camp.Description);
        Assert.Contains("Alice, killed by a goblin.", bobOut.Text);
    }

    [Fact]
    public void APlaceNamesOnlyItsLastFewDead()
    {
        var (engine, _) = WorldFixture.NewEngine();
        var camp = engine.World.FindLocation(3)!;

        foreach (var name in new[] { "One", "Two", "Three", "Four" })
        {
            var (session, _) = WorldFixture.Join(engine, name);
            engine.HandleInput(session, "east");
            WorldFixture.Kill(engine, session, "the test");
        }

        Assert.DoesNotContain("One, killed", camp.Description);
        Assert.Contains("Four, killed", camp.Description);
        Assert.Equal(3, camp.Description.Split("killed by").Length - 1);
    }
}

